If we disable InstCombine in optimize_module, it will pass. But I haven't figured out why yet. It is not obvious to me by looking at the differences in ptx: disable-opt against with-opt
[disable-opt-llir.txt](https://github.com/openai/participant10/files/14028589/disable-opt-llir.txt)
[disable-opt-ptx.txt](https://github.com/openai/participant10/files/14028590/disable-opt-ptx.txt)
[with-opt-llir.txt](https://github.com/openai/participant10/files/14028592/with-opt-llir.txt)
[with-opt-ptx.txt](https://github.com/openai/participant10/files/14028593/with-opt-ptx.txt)


```
@@ -28,8 +26,8 @@
 $L__tmp0:
 	.loc	1 9 36
 	mov.u32 	%r6, %tid.x;
-	and.b32  	%r7, %r6, 127;
-	shl.b32 	%r8, %r7, 1;
+	shl.b32 	%r7, %r6, 1;
+	and.b32  	%r8, %r7, 254;
 	.loc	1 8 28
 	// begin inline asm
 	mov.u32 %r1, %ctaid.x;
@@ -60,19 +58,14 @@
 	mov.u32 %r3, 0x0;
 	@%p1 ld.global.v2.b32 { %r2, %r3 }, [ %rd1 + 0 ];
 	// end inline asm
-	mov.b32 	%f1, %r2;
-	mov.b32 	%f2, %r3;
 	.loc	1 15 33
-	setp.eq.s32 	%p3, %r11, 0;
-	.loc	1 15 41
-	selp.f32 	%f3, 0f00000000, %f1, %p3;
-	selp.f32 	%f4, 0f00000000, %f2, %p3;
+	setp.eq.s32 	%p3, %r10, 0;
 	.loc	1 16 23
 	mul.wide.s32 	%rd6, %r10, 4;
 	add.s64 	%rd2, %rd4, %rd6;
 	.loc	1 16 31
-	mov.b32 	%r4, %f3;
-	mov.b32 	%r5, %f4;
+	selp.b32 	%r4, 0, %r2, %p3;
+	selp.b32 	%r5, 0, %r3, %p3;
 	// begin inline asm
 	@%p1 st.global.v2.b32 [ %rd2 + 0 ], { %r4, %r5 };
 	// end inline asm
```

It looks like the predication is different in the two cases.

Disable opt:

```
	mov.u32 %r1, %ctaid.x;
	shl.b32 	%r9, %r1, 8;
	or.b32  	%r10, %r9, %r8;
	shr.s32 	%r11, %r10, 1;
        setp.eq.s32 	%p3, %r11, 0;
```

With opt:

```
	mov.u32 %r1, %ctaid.x;
	shl.b32 	%r9, %r1, 8;
	or.b32  	%r10, %r9, %r8;
        setp.eq.s32 	%p3, %r10, 0;
```

> > Yes, but the problem is that r10 is supposed to be a multiple of 2, so checking it against 0 vs. checking (r10 >> 1) against 0 should be the same?
> 
> I see, it could make a difference if r10 has value of 1?
Yes if r10 can be 1.

`	mov.u32 	%r6, %tid.x;
	shl.b32 	%r7, %r6, 1;
	and.b32  	%r8, %r7, 254;

	mov.u32 %r1, %ctaid.x;

	shl.b32 	%r9, %r1, 8;
	or.b32  	%r10, %r9, %r8;`
%r8 should be  a multiple of 2 and %r9 should be a multiple of 2.

